// The CLI never receives the root key. Only an unlocked approval client can
// export it, sealed to the public key generated by the destination iOS app.
export async function createIOSTransfer(requestText: string, vaultKey: CryptoKey, origin: string) {
    const request = JSON.parse(requestText);
    if (request.type !== "sickrat-ios-transfer-request" || request.version !== 1 || request.origin !== origin ||
        request.publicKey?.kty !== "EC" || request.publicKey?.crv !== "P-256") {
        throw new Error("Use the transfer request generated by the iOS app for this vault.");
    }
    const recipient = await crypto.subtle.importKey("jwk", request.publicKey, { name: "ECDH", namedCurve: "P-256" }, false, []);
    const ephemeral = await crypto.subtle.generateKey({ name: "ECDH", namedCurve: "P-256" }, true, ["deriveBits"]);
    const shared = await crypto.subtle.deriveBits({ name: "ECDH", public: recipient }, ephemeral.privateKey, 256);
    const material = await crypto.subtle.importKey("raw", shared, "HKDF", false, ["deriveKey"]);
    const encoder = new TextEncoder();
    const wrapping = await crypto.subtle.deriveKey({ name: "HKDF", hash: "SHA-256", salt: encoder.encode("sickrat:ios-transfer-salt:v1"), info: encoder.encode("sickrat:ios-transfer:v1") }, material, { name: "AES-GCM", length: 256 }, false, ["encrypt"]);
    const b64 = (bytes: Uint8Array) => btoa(String.fromCharCode(...bytes)).replaceAll("+", "-").replaceAll("/", "_").replaceAll("=", "");
    const raw = new Uint8Array(await crypto.subtle.exportKey("raw", vaultKey));
    try {
        const iv = crypto.getRandomValues(new Uint8Array(12));
        const plaintext = encoder.encode(JSON.stringify({ origin, key: b64(raw), expiresAt: new Date(Date.now() + 600_000).toISOString().replace(/\.\d{3}Z$/, "Z") }));
        try {
            const ciphertext = await crypto.subtle.encrypt({ name: "AES-GCM", iv }, wrapping, plaintext);
            return { type: "sickrat-ios-transfer", version: 1, ephemeralPublicKey: await crypto.subtle.exportKey("jwk", ephemeral.publicKey), ciphertext: b64(new Uint8Array(ciphertext)), iv: b64(iv) };
        } finally { plaintext.fill(0); }
    } finally { raw.fill(0); }
}
